insert into public.catalogos(codigo,nome,descricao) values ('etapas','Etapas de ensino','Catálogo importado da referência PPP v10.2') on conflict(codigo) do update set nome=excluded.nome,descricao=excluded.descricao;
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('etapas','ei','Educação Infantil',1,'DCNEI · art. 29 da LDB','A Educação Infantil, primeira etapa da Educação Básica, tem como eixos norteadores as interações, a ludicidade e a brincadeira, conforme as Diretrizes Curriculares Nacionais para a Educação Infantil. A proposta pedagógica integra os direitos de aprendizagem — conviver, brincar, participar, explorar, expressar e conhecer-se — assegurando ambientes desafiadores e intencionalidade pedagógica nas interações cotidianas. O acompanhamento do desenvolvimento da criança ocorre por múltiplos registros, sendo vedado o uso da avaliação com objetivo de seleção, promoção, classificação ou retenção nesta etapa.','Etapa basilar do processo de escolarização. A avaliação se dá por relatórios, fotografias, desenhos e outros registros — nunca para promover ou reter. Na transição para os Anos Iniciais, o PPP deve expressar continuidade sem antecipar conteúdos da etapa seguinte.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','ei',1,'Os direitos de aprendizagem e os campos de experiência na rotina.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','ei',2,'As formas de registro do desenvolvimento da criança.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','ei',3,'A transição estruturada para o Ensino Fundamental, sem antecipação de conteúdos.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','ei',4,'As especificidades socioculturais e linguísticas do público atendido.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('etapas','efai','Ensino Fundamental — Anos Iniciais',2,'arts. 45, 46 e 48 da Resolução SEE nº [nº a publicar], de 2026','Os Anos Iniciais do Ensino Fundamental garantem a transição entre os campos de experiências da Educação Infantil e a consolidação da alfabetização e do letramento. Asseguram também o domínio do cálculo matemático e das demais habilidades previstas no Currículo Referência de Minas Gerais, nos termos do art. 14 da Resolução SEE nº [nº a publicar], de 2026. A alfabetização e o letramento constituem direitos fundamentais de aprendizagem e base para o desenvolvimento das demais áreas do conhecimento, com acompanhamento sistemático do progresso dos estudantes e intervenções pedagógicas oportunas.','Alfabetização e letramento no centro. O PPP precisa explicitar concepções, estratégias e ações para consolidar leitura, escrita e raciocínio matemático — e a recomposição das aprendizagens como ação permanente, não como programa à parte.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','efai',1,'As concepções e estratégias de alfabetização e letramento.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','efai',2,'O acompanhamento sistemático do progresso, estudante a estudante.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','efai',3,'As intervenções e a recomposição das aprendizagens integradas ao planejamento.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','efai',4,'O acolhimento, os vínculos afetivos e a parceria com as famílias.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('etapas','efaf','Ensino Fundamental — Anos Finais',3,'arts. 45 e 47 da Resolução SEE nº [nº a publicar], de 2026','Os Anos Finais do Ensino Fundamental promovem o aprofundamento das aprendizagens, o fortalecimento da autonomia e o desenvolvimento integral dos estudantes, consideradas as especificidades das adolescências, nos termos da Resolução SEE nº [nº a publicar], de 2026. A escola organiza estratégias de transição que auxiliem os estudantes na compreensão das mudanças relacionadas à organização curricular, às metodologias de ensino, às formas de avaliação e às novas relações estabelecidas no ambiente escolar.','A transição do 5º para o 6º ano e a preparação do 9º ano para o Ensino Médio concentram os maiores riscos de ruptura. O PPP deve prever acolhimento, escuta, avaliações diagnósticas, projetos integradores e ações articuladas entre professores dos diferentes segmentos.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','efaf',1,'As ações de acolhimento e ambientação na chegada ao 6º ano.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','efaf',2,'A preparação do 9º ano para a mudança de nível de ensino.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','efaf',3,'A articulação entre os professores dos diferentes segmentos.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','efaf',4,'O enfrentamento da distorção idade/ano de escolaridade.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('etapas','em','Ensino Médio',4,'Lei nº 14.945/2024 · Res. CNE/CEB nº 2/2024','O Ensino Médio organiza-se em Formação Geral Básica e Itinerários Formativos. No ensino regular, destinam-se à Formação Geral Básica, no mínimo, 2.400 (duas mil e quatrocentas) horas. São observadas a Lei nº 14.945/2024, as Diretrizes Curriculares Nacionais para o Ensino Médio (Resolução CNE/CEB nº 2/2024) e o Currículo Referência do Ensino Médio de Minas Gerais. O Projeto de Vida assume papel estruturante na orientação dos percursos formativos das juventudes, assegurada a indissociabilidade entre Formação Geral Básica e Itinerários Formativos.','Centralidade das juventudes, organização por áreas do conhecimento e eixos estruturantes, integração curricular e Projeto de Vida como estruturante. O PPP deve pactuar novos tempos e espaços de aprendizagem e definir a articulação entre a Coordenação do Novo Ensino Médio e a equipe pedagógica.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','em',1,'Os itinerários formativos e as eletivas ofertados, e os critérios de escolha.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','em',2,'O Projeto de Vida como eixo orientador do percurso formativo.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','em',3,'A indissociabilidade entre Formação Geral Básica e Itinerários.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('etapas','em',4,'A articulação entre a Coordenação do Novo Ensino Médio e a equipe pedagógica.');
insert into public.catalogos(codigo,nome,descricao) values ('modalidades','Modalidades e formas de oferta','Catálogo importado da referência PPP v10.2') on conflict(codigo) do update set nome=excluded.nome,descricao=excluded.descricao;
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','parcial','Ensino regular em tempo parcial',1,'organização anual · art. 24 da LDB','A oferta regular em tempo parcial organiza-se em regime anual, observadas a matriz curricular vigente, a carga horária mínima legal e o calendário escolar homologado. Assegura o cumprimento do currículo e das aprendizagens essenciais previstas na Base Nacional Comum Curricular (BNCC) e no Currículo Referência de Minas Gerais.','Forma comum de oferta, referência para as demais. Mesmo aqui o PPP precisa dizer como a escola organiza tempos, planejamento coletivo e acompanhamento das aprendizagens — não basta anexar a matriz curricular.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','parcial',1,'A matriz curricular praticada e a distribuição da carga horária.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','parcial',2,'A organização dos tempos de planejamento coletivo.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','parcial',3,'Os critérios de avaliação e as estratégias de recuperação.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','efti','Ensino Fundamental em Tempo Integral (EFTI)',2,'Decreto nº 47.227/2017 · Res. CNE/CEB nº 7/2025','O Ensino Fundamental em Tempo Integral amplia a jornada escolar e reorganiza o tempo pedagógico com planejamento intencional voltado à formação integral de estudantes autônomos, solidários e competentes. A proposta materializa-se por meio de atividades integradoras, do protagonismo estudantil, da integração curricular e do uso pedagógico dos territórios de aprendizagem do entorno. Observa as Diretrizes Operacionais Nacionais instituídas pela Resolução CNE/CEB nº 7/2025 e o Decreto Estadual nº 47.227/2017.','A escola deve explicitar a carga horária da oferta — 35 ou 45 horas semanais — e informar se oferta Educação Bilíngue. Ampliar a jornada sem intencionalidade formativa não é educação integral: é ocupação de turno.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','efti',1,'A carga horária semanal ofertada: 35 ou 45 horas.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','efti',2,'A indicação, quando for o caso, da oferta de Educação Bilíngue.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','efti',3,'As atividades integradoras e sua articulação com o currículo.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','efti',4,'Os espaços do entorno mobilizados como territórios de aprendizagem.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','emti','Ensino Médio em Tempo Integral (EMTI)',3,'oferta em tempo integral · Decreto nº 47.227/2017','O Ensino Médio em Tempo Integral desenvolve-se segundo quatro Princípios Educativos: Pedagogia da Presença, Quatro Pilares da Educação, Educação Interdimensional e Trabalho e Protagonismo. Orienta-se por quatro Eixos Formativos: Formação Acadêmica de Excelência, Formação Profissional de Excelência, Formação para a Vida e Formação de Competências para o Século XXI. O modelo de gestão próprio da oferta em tempo integral orienta-se pela descentralização, pela delegação planejada, pelo ciclo de melhoria contínua e pela parceria.','É obrigatório indicar a especificidade da oferta: Propedêutico, Profissional ou Bilíngue. O PPP precisa revelar tanto o modelo pedagógico quanto o modelo de gestão — os dois são constitutivos do EMTI.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','emti',1,'A especificidade da oferta: propedêutica, profissional ou bilíngue.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','emti',2,'Os Princípios Educativos e os Eixos Formativos na prática da escola.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','emti',3,'O modelo de gestão adotado na oferta em tempo integral.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','ept','Educação Profissional Técnica de Nível Médio (EPT)',4,'Res. CEE/MG nº 484/2021 · Decreto nº 12.603/2025','A Educação Profissional Técnica de Nível Médio integra-se ao Projeto Político-Pedagógico como parte constitutiva da identidade da escola, e não como ação paralela ao currículo regular, articulando educação, trabalho, ciência, cultura e tecnologia. Os cursos ofertados vinculam-se obrigatoriamente aos Planos de Curso, aos Projetos Pedagógicos de Curso, às matrizes curriculares e às ementas elaborados conforme o Catálogo Nacional de Cursos Técnicos e as diretrizes da SEE/MG. São observadas a Resolução CEE/MG nº 484/2021 e a Política Nacional de Educação Profissional e Tecnológica, instituída pelo Decreto nº 12.603/2025.','Formas possíveis: integrada, concomitante, concomitante intercomplementar, subsequente, EMTI Profissional, 5º Itinerário Formativo e EJA Profissional. O diagnóstico da escola deve considerar os Arranjos Produtivos Locais — a oferta precisa dialogar com o território.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','ept',1,'As formas de oferta e os cursos técnicos, com seus Planos de Curso e PPC.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','ept',2,'A articulação entre Formação Geral Básica e Formação Técnica Específica.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','ept',3,'Os Arranjos Produtivos Locais e as demandas do território.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','ept',4,'O estágio supervisionado e as certificações intermediárias, quando previstas.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','ept',5,'As estratégias de inclusão e acessibilidade dos estudantes da Educação Especial na EPT.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','esp','Educação Especial',5,'Res. SEE nº 4.256/2020 · art. 58 da LDB','A Educação Especial, modalidade que perpassa todos os níveis, etapas e modalidades, assegura recursos de acessibilidade, formação de professores e a oferta do Atendimento Educacional Especializado (AEE) aos estudantes com deficiência, transtorno do espectro autista e altas habilidades ou superdotação, nos termos da Resolução SEE nº 4.256/2020. O Plano de Desenvolvimento Individual (PDI) é documento obrigatório de acompanhamento, construído com a participação de todos os envolvidos na escolarização do estudante. Cabe ao Especialista em Educação Básica (EEB) articular e garantir sua elaboração.','Dois instrumentos precisam estar institucionalizados no PPP: o AEE, que complementa ou suplementa a formação, e o PDI, obrigatório e construído a partir do histórico de vida do estudante, das avaliações diagnósticas, do planejamento e do acompanhamento.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','esp',1,'A institucionalização da oferta do AEE e a organização da sala de recursos.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','esp',2,'A construção do PDI e a responsabilidade do EEB por articulá-la.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','esp',3,'As flexibilizações curriculares, de avaliação e os recursos de acessibilidade.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','esp',4,'A atuação dos profissionais de apoio e a articulação com as famílias.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','bilingue','Educação Bilíngue de Surdos',6,'Lei nº 14.191/2021','A Educação Bilíngue de Surdos adota a Língua Brasileira de Sinais (Libras) como primeira língua e a Língua Portuguesa escrita como segunda língua. Assegura profissionais habilitados e recursos didáticos adequados aos estudantes surdos, surdo-cegos e com deficiência auditiva, nos termos da Lei nº 14.191/2021.','Modalidade autônoma na LDB desde 2021. Exige Libras como língua de instrução, materiais adequados e profissionais habilitados — tradutores-intérpretes, instrutores e professores bilíngues.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','bilingue',1,'A organização linguística do ensino e o uso da Libras como primeira língua.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','bilingue',2,'Os profissionais habilitados disponíveis e sua forma de atuação.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','bilingue',3,'As adaptações de material didático e dos instrumentos de avaliação.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','campo','Educação Escolar do Campo',7,'Res. SEE nº 2.820/2015 · art. 28 da LDB','A Educação Escolar do Campo observa as Diretrizes para a Educação Básica das Escolas do Campo instituídas pela Resolução SEE nº 2.820/2015, reconhecendo a população camponesa como protagonista dos processos educativos e não como beneficiária. A organização escolar é própria, com adequação do calendário às condições de trabalho e às formas de vida do campo. Os recursos didáticos, pedagógicos, tecnológicos, culturais e literários atendem ao contexto local, à identidade e às tradições dessas populações.','Não é a escola urbana transposta para a zona rural. Onde há Pedagogia da Alternância, tempo escola e tempo comunidade são igualmente tempos formativos. O trabalho familiar e os ciclos produtivos organizam o calendário.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','campo',1,'A adequação do calendário às condições de trabalho e vida no campo.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','campo',2,'Os recursos didáticos próprios da modalidade.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','campo',3,'O compromisso com os saberes culturais locais, a memória e a história da comunidade.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','ind','Educação Escolar Indígena',8,'Res. CNE/CEB nº 5/2012 · Lei nº 22.445/2016','A Educação Escolar Indígena é oferecida em instituições próprias e específicas. Pauta-se pelos princípios da igualdade social, da diferença, da especificidade, do bilinguismo e da organização comunitária. Tem respaldo na Constituição Federal, na Lei nº 9.394/1996, no Decreto nº 6.861/2009, na Resolução CNE/CEB nº 5/2012 e, no âmbito estadual, na Lei nº 22.445/2016. Reconhece a centralidade do território para o bem viver e para os processos formativos, com currículo flexível e diferenciado e calendário adequado às atividades produtivas, rituais e climáticas do território.','O PPP é elaborado de forma autônoma e coletiva, com participação direta de professores, estudantes, lideranças, mais velhos e especialistas em saberes tradicionais. A revisão e a aprovação exigem consulta livre, prévia e informada, na forma da Convenção nº 169 da Organização Internacional do Trabalho (OIT).',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','ind',1,'A participação das lideranças e dos mais velhos na construção do documento.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','ind',2,'O tratamento da língua materna, da oralidade e da interculturalidade.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','ind',3,'O calendário diferenciado e a gestão territorial e ambiental.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','ind',4,'O mecanismo de consulta livre, prévia e informada.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','qui','Educação Escolar Quilombola',9,'Res. CNE/CEB nº 8/2012 · Res. SEE/MG nº 3.658/2017','A Educação Escolar Quilombola destina-se ao atendimento das populações quilombolas rurais e urbanas, com pedagogia própria em respeito às especificidades étnico-culturais, nos termos da Resolução CNE/CEB nº 8/2012 e da Resolução SEE nº 3.658/2017. O Projeto Político-Pedagógico relaciona-se intrinsecamente com a realidade histórica, regional, política, sociocultural, territorial e econômica dessas comunidades, sendo construído de forma autônoma e coletiva, em relação dialógica com as lideranças e as organizações existentes no território.','O diagnóstico precisa envolver toda a comunidade quilombola. Currículo, calendário e materiais reconhecem a memória coletiva, a oralidade, o trabalho e a relação com a terra.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','qui',1,'O diagnóstico construído com participação da comunidade quilombola.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','qui',2,'Os princípios da Educação Escolar Quilombola na organização pedagógica.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','qui',3,'As datas de relevância histórica e cultural contempladas no calendário.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','eja','Educação de Jovens e Adultos (EJA)',10,'art. 37 da LDB · Res. CNE/CEB nº 3/2025','A Educação de Jovens e Adultos destina-se àqueles que não tiveram acesso ou continuidade de estudos na idade própria e constitui instrumento para a educação e a aprendizagem ao longo da vida, nos termos do art. 37 da Lei nº 9.394/1996 e das Diretrizes Operacionais Nacionais estabelecidas pela Resolução CNE/CEB nº 3/2025. O Projeto Político-Pedagógico reconhece os estudantes como sujeitos de direitos, portadores de saberes construídos em suas trajetórias de vida e de trabalho, valorizando os conhecimentos prévios e a contextualização curricular.','Quatro perguntas orientam a escrita: quem é o estudante da EJA? quais suas expectativas com a escolarização? como suas experiências de vida podem nutrir as práticas educativas? onde a escola quer chegar? Nas ofertas articuladas à formação profissional, o currículo aproxima conhecimento escolar, realidade social e mundo do trabalho.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','eja',1,'O perfil real dos estudantes e suas condições de vida e trabalho.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','eja',2,'O aproveitamento de estudos e das experiências anteriores.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','eja',3,'As estratégias de acolhimento e de enfrentamento da evasão.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','eja',4,'O tratamento dado à articulação entre conhecimento escolar, realidade social e formação profissional, quando houver.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','cesec','Centro Estadual de Educação Continuada (CESEC)',11,'Res. SEE/MG nº 5.258/2026','O Projeto Político-Pedagógico das unidades do CESEC é elaborado e atualizado em conformidade com a Resolução SEE nº 5.258/2026. Assegura-se a participação de todos os segmentos representativos da escola e da comunidade, com apoio e orientação das equipes pedagógicas da Superintendência Regional de Ensino. São observadas as Diretrizes Operacionais Nacionais para a Educação de Jovens e Adultos e, quando houver, as normativas do Ensino Médio e da Educação Profissional e Tecnológica.','Atendimento individualizado e por certificação de competências exige do PPP clareza sobre fluxos de matrícula, organização dos plantões pedagógicos e acompanhamento do percurso de cada estudante.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','cesec',1,'A organização do atendimento e dos plantões pedagógicos.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','cesec',2,'Os fluxos de matrícula, avaliação e certificação.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','cesec',3,'A articulação com a Educação Profissional, quando houver.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','prisional','Escola no Sistema Prisional',12,'Res. Conjunta SEJUSP/SEE nº 21/2023','A oferta da Educação Básica em unidades prisionais realiza-se na modalidade Educação de Jovens e Adultos (EJA), observadas a Resolução CEE nº 2/2010 e a Resolução Conjunta SEJUSP/SEE nº 21/2023. São considerados a identidade do sujeito e seu repertório, o contexto da unidade prisional e as normas de segurança. O Projeto Político-Pedagógico contempla a totalidade das unidades prisionais sob responsabilidade de atendimento da escola.','A construção envolve diretores, Especialistas em Educação Básica, professores, gestores da unidade prisional, o Analista Educacional (ANEDS) ou Pedagogo, policiais penais e demais servidores. A escolarização integra o processo de ressocialização previsto na execução penal.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','prisional',1,'A articulação com a equipe da unidade prisional e as normas de segurança.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','prisional',2,'A totalidade das unidades atendidas pela escola.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','prisional',3,'As estratégias de continuidade dos estudos após o desligamento.');
insert into public.itens_catalogo(catalogo_codigo,codigo,rotulo,ordem,referencia,texto_documento,texto_formativo,ativo) values ('modalidades','socio','Escola no Sistema Socioeducativo',13,'SINASE · Res. Conjunta SEE/SEJUSP nº 09/2021','A oferta escolar a adolescentes e jovens em cumprimento de medida socioeducativa fundamenta-se na singularidade do público atendido. Contempla estratégias que garantam a progressão com qualidade nas etapas da Educação Básica, a reconstrução dos vínculos escolares e a correção da distorção idade/ano de escolaridade. Observa a Lei nº 12.594/2012, que institui o Sistema Nacional de Atendimento Socioeducativo (SINASE), a Resolução CNE/CEB nº 3/2016 e a Resolução Conjunta SEE/SEJUSP nº 09/2021.','O trabalho pedagógico é organizado com a equipe multidisciplinar da SEJUSP, sem fragmentação do conhecimento, a partir de projetos que considerem a trajetória educacional, a história e o território de cada estudante.',true) on conflict(catalogo_codigo,codigo) do update set rotulo=excluded.rotulo,ordem=excluded.ordem,referencia=excluded.referencia,texto_documento=excluded.texto_documento,texto_formativo=excluded.texto_formativo,ativo=true;
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','socio',1,'A articulação com a equipe multidisciplinar da SEJUSP.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','socio',2,'As estratégias interdisciplinares e os projetos pedagógicos adotados.');
insert into public.orientacoes_itens_catalogo(catalogo_codigo,item_codigo,ordem,texto) values ('modalidades','socio',3,'A correção da distorção idade/ano e a continuidade dos estudos.');
